import{_ as r,g as d,o as c,c as i,j as e,a as n,k as o,a2 as s}from"./chunks/framework.DXa1R37q.js";const l={class:"diagram-links"},p=["href"],v={class:"diagram-frame editorial"},u=["src"],g=JSON.parse('{"title":"Lifecycle and authority boundaries","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"learn/lifecycle.md","filePath":"learn/lifecycle.md","lastUpdated":1793135521000}'),h={name:"learn/lifecycle.md"},m=Object.assign(h,{setup(f){const t=d("/diagrams/neottia-lifecycle.html");return(y,a)=>(c(),i("div",null,[a[0]||(a[0]=e("h1",{id:"lifecycle-and-authority-boundaries",tabindex:"-1"},[n("Lifecycle and authority boundaries "),e("a",{class:"header-anchor",href:"#lifecycle-and-authority-boundaries","aria-label":'Permalink to "Lifecycle and authority boundaries"'},"​")],-1)),a[1]||(a[1]=e("p",null,"Neottia installs seven public commands. Four advance delivery work. Two help recover context without silently advancing it. Adopt reorganizes existing project documents through a separate approval and pull-request workflow.",-1)),e("div",l,[e("a",{href:o(t),target:"_blank",rel:"noreferrer"},"Open the interactive lifecycle in a new tab",8,p)]),e("div",v,[e("iframe",{src:o(t),title:"Interactive Neottia lifecycle and authority diagram",loading:"lazy"},null,8,u)]),a[2]||(a[2]=s('<h2 id="delivery-commands" tabindex="-1" data-v-86c95007>Delivery commands <a class="header-anchor" href="#delivery-commands" aria-label="Permalink to &quot;Delivery commands&quot;" data-v-86c95007>​</a></h2><table tabindex="0" data-v-86c95007><thead data-v-86c95007><tr data-v-86c95007><th data-v-86c95007>Command</th><th data-v-86c95007>Owns</th><th data-v-86c95007>Required stop</th></tr></thead><tbody data-v-86c95007><tr data-v-86c95007><td data-v-86c95007><code data-v-86c95007>/neottia-plan</code></td><td data-v-86c95007>Requirements, repository evidence, owning Epic, child work, and design scope</td><td data-v-86c95007>Stop for current scope or design approval</td></tr><tr data-v-86c95007><td data-v-86c95007><code data-v-86c95007>/neottia-build</code></td><td data-v-86c95007>Only the approved implementation scope</td><td data-v-86c95007>Stop with implementation evidence for Verify</td></tr><tr data-v-86c95007><td data-v-86c95007><code data-v-86c95007>/neottia-verify</code></td><td data-v-86c95007>Requirement coverage, checks, user-visible behavior, and verdict</td><td data-v-86c95007>Return defects to Build or present a current pass verdict</td></tr><tr data-v-86c95007><td data-v-86c95007><code data-v-86c95007>/neottia-release</code></td><td data-v-86c95007>Release metadata and one explicitly selected action</td><td data-v-86c95007>Stop before any action that lacks fresh authorization</td></tr></tbody></table><h2 id="recovery-commands" tabindex="-1" data-v-86c95007>Recovery commands <a class="header-anchor" href="#recovery-commands" aria-label="Permalink to &quot;Recovery commands&quot;" data-v-86c95007>​</a></h2><ul data-v-86c95007><li data-v-86c95007><code data-v-86c95007>/neottia-continue</code> reads durable records and recommends exactly one next public command. It does not invoke that command.</li><li data-v-86c95007><code data-v-86c95007>/neottia-refresh</code> reloads configuration, provider records, repository state, and source-control state. It reports drift without changing phase.</li></ul><h2 id="project-adoption" tabindex="-1" data-v-86c95007>Project adoption <a class="header-anchor" href="#project-adoption" aria-label="Permalink to &quot;Project adoption&quot;" data-v-86c95007>​</a></h2><p data-v-86c95007>Use <code data-v-86c95007>/neottia-adopt</code> when an existing repository has legacy documents, instruction files, issue records, or design records that need to move into the configured Neottia model.</p><p data-v-86c95007>Adopt reads repository authority first and performs read-only discovery. It does not execute project code, hooks, task runners, installers, builds, tests, or dependency commands. It reports an exact document-operation plan and stops for approval before mutation. Every irreversible deletion needs separate approval.</p><p data-v-86c95007>After approval, Adopt verifies a dedicated non-default branch or isolated workspace, a usable Git remote, credentials, and a pull-request provider before document mutation. It never changes the default branch. It applies only approved document and Neottia-facing configuration operations, preserves originals until provider imports are verified, and never changes application source, dependencies, build systems, CI, or project-specific policy. It bypasses repository hooks for commit and push and never runs target-project validation.</p><p data-v-86c95007>Push and draft pull-request creation each need fresh action-specific approval. Adopt reports the draft pull-request URL and never merges, closes, or auto-approves it. Later runs report only remaining drift.</p><h2 id="approval-rules" tabindex="-1" data-v-86c95007>Approval rules <a class="header-anchor" href="#approval-rules" aria-label="Permalink to &quot;Approval rules&quot;" data-v-86c95007>​</a></h2><p data-v-86c95007>Approval is narrow and current:</p><ul data-v-86c95007><li data-v-86c95007>Plan approval covers the recorded implementation scope.</li><li data-v-86c95007>It does not authorize merge, publication, deployment, remote closure, or destructive cleanup.</li><li data-v-86c95007>Release can prepare one action, but the action still needs explicit owner authorization.</li><li data-v-86c95007>A confirmed defect becomes one canonical Bug and returns through Build.</li><li data-v-86c95007>A stop records the exact revision, commits, checks, status, and recommended next command in an append-only checkpoint.</li></ul><p data-v-86c95007>These rules remain the same in Pi, OpenCode, and Claude Code. Adapters change host syntax and paths, not lifecycle authority.</p><p data-v-86c95007>Read the <a href="/projects/neottia/sdlc/protocol" data-v-86c95007>operating protocol reference</a> for the full checkpoint and ownership contract. See <a href="/projects/neottia/reference/diagrams" data-v-86c95007>diagram sources and attribution</a> for evidence and license details.</p>',14))]))}}),_=r(m,[["__scopeId","data-v-86c95007"]]);export{g as __pageData,_ as default};
